import { expect, type Page } from "@playwright/test";

import { LLM_TIMEOUT } from "@e2e/config";

export const getLocators = (page: Page) => {
  const panel = page.getByTestId("memory-panel");
  const section = (name: string) => panel.getByTestId(`${name}-section`);

  return {
    panel,
    panelHeading: panel.getByRole("heading", { name: "Memory" }),
    sectionHeading: (name: string) => panel.getByRole("heading", { name }),
    section,
    entries: panel.getByTestId("memory-entry"),
    sourceBadges: panel.getByTestId("memory-source"),
    slot: (sectionName: string, slotName: string) =>
      section(sectionName).getByTestId(`slot-${slotName}`),
    slotValue: (sectionName: string, slotName: string) =>
      section(sectionName).getByTestId(`slot-${slotName}`).getByTestId("slot-value"),
  };
};

export const actions = (page: Page) => {
  const locators = getLocators(page);

  return {
    clickSlot: async (sectionName: string, slotName: string) => {
      await locators.slot(sectionName, slotName).click();
    },
  };
};

export const assertions = (page: Page) => {
  const locators = getLocators(page);

  return {
    panelIsVisible: async () => {
      await expect(
        locators.panelHeading,
        "Memory panel should be visible in Memory view",
      ).toBeVisible();
    },
    sectionIsVisible: async (sectionName: string) => {
      await expect(
        locators.sectionHeading(sectionName),
        `${sectionName} slots heading should be visible in Memory view`,
      ).toBeVisible();
      await expect(
        locators.section(sectionName),
        `${sectionName} slots section should be visible in Memory view`,
      ).toBeVisible();
    },
    slotIsVisible: async (sectionName: string, slotName: string, slotValue?: string) => {
      await expect(
        locators.slot(sectionName, slotName),
        `Slot "${slotName}" should be visible in the ${sectionName} section`,
      ).toBeVisible();

      if (slotValue !== undefined) {
        await expect(
          locators.slotValue(sectionName, slotName),
          `Slot "${slotName}" should show value "${slotValue}" in the ${sectionName} section`,
        ).toContainText(slotValue);
      }
    },
    sectionIsHidden: async (sectionName: string) => {
      await expect(
        locators.section(sectionName),
        `${sectionName} section should not be visible in Memory view`,
      ).toBeHidden();
    },
    slotIsHidden: async (sectionName: string, slotName: string) => {
      await expect(
        locators.slot(sectionName, slotName),
        `Slot "${slotName}" should be hidden in the ${sectionName} section`,
      ).toBeHidden();
    },
    entryCountAtLeast: async (count: number, timeout = LLM_TIMEOUT) => {
      await expect
        .poll(async () => await locators.entries.count(), {
          message: `Memory pane should render at least ${count} memory entries`,
          timeout,
        })
        .toBeGreaterThanOrEqual(count);
    },
    entryHasValue: async (index: number) => {
      await expect(
        locators.entries.nth(index).getByTestId("slot-value"),
        `Memory entry ${index} should render a value cell`,
      ).toBeVisible();
    },
    hasProvenanceBadge: async () => {
      await expect(
        locators.sourceBadges.first(),
        "At least one memory entry should carry a provenance badge (tool / LLM / engine)",
      ).toBeVisible();
    },
  };
};
